nextflow_process {
    name "TRUVARI_BENCH"
    script "../main.nf"
    process "TRUVARI_BENCH"

    test("summarize one matching deletion") {
        options "-with-docker"

        when {
            process {
                """
                input[0] = record(
                    id: 'sample',
                    vcf: file("${moduleDir}/tests/data/sample.sv.vcf.gz", checkIfExists: true),
                    tbi: file("${moduleDir}/tests/data/sample.sv.vcf.gz.tbi", checkIfExists: true),
                    truth_vcf: file("${moduleDir}/tests/data/truth.vcf.gz", checkIfExists: true),
                    truth_tbi: file("${moduleDir}/tests/data/truth.vcf.gz.tbi", checkIfExists: true),
                    bed: file("${moduleDir}/tests/data/target.bed", checkIfExists: true)
                )
                """
            }
        }

        then {
            assert process.success
            def summary = new groovy.json.JsonSlurper().parse(file(process.out[0].summary[0]))
            assert summary['TP-base'] == 1
            assert summary.FP == 0
            assert summary.FN == 0
            assert summary.f1 == 1.0
            assert file(process.out[0].log[0]).text.contains('truvari bench')
            assert new File("${process.out[0].report_dir[0]}/fp.vcf.gz").isFile()
            assert new File("${process.out[0].report_dir[0]}/fn.vcf.gz").isFile()
        }
    }
}
